INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dali','大理','["大理国","后大理"]','白族',NULL,'cn','east_asia',937,1,NULL,'year',1253,12,NULL,'month',11244,15047,'ochre',NULL,NULL,'937年段思平联合滇东三十七部推翻大义宁，建立大理国，以羊苴咩城为都，政治中心在洱海地区。大理承接南诏的地域与部分制度，同时发展出自身的政区和官僚体系；段氏世袭为主，高氏相国长期辅政。1094年高升泰改国号大中，1096年段氏复位。大理与宋保持朝贡、使节及马匹等贸易往来，佛教深刻影响王室与地方社会。1253年蒙古军攻取大理，段氏归降，此后仍以地方总管身份延续治理。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('nanzhao','南诏','["大蒙","蒙舍诏","大礼","大封民"]',NULL,NULL,'cn','east_asia',649,1,NULL,'year',902,12,NULL,'month',7788,10835,'ochre',NULL,NULL,'7世纪中叶，细奴逻在洱海地区建立蒙舍诏势力。皮逻阁继承其父盛逻皮的统治，在唐朝支持下于738年统一六诏，南诏以太和城为中心扩张，此后曾与唐、吐蕃交战。902年郑买嗣取代蒙氏，南诏结束。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-lianyi','段廉义','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理段氏君主，承接段思廉，在位五年。1080年为杨义贞所杀并发生短暂篡位，段氏随后复位；这场政变是大理十一世纪后期的重要王位危机；在位1075—1080年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段廉义"}]','上德皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-shouhui','段寿辉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段廉义遇弑、杨义贞政权被推翻后即位的大理君主，使用上明年号。其在位约一年即让位于段正明，处于政变后恢复段氏统治的阶段；在位1080—1081年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段寿辉"}]','上明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sicong','段思聪','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思良之后的大理君主，在位时期跨越十世纪中叶。其年号见于后世大理君主名录；由于相关史料简略，具体政事与对外关系难以详考；在位952—968年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思聪"}]','至道广慈皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-silian','段思廉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思平后裔、段素兴之后继位的大理君主，庙号世宗，在位三十一年。其长统治连接大理早期与中期，后由段廉义继位；现存材料对其朝政细节有限；在位1044—1075年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思廉"}]','孝德皇帝','世宗','大理世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-siliang','段思良','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思平之弟，继段思英之后为大理第三位君主。其在位七年，处于新王朝早期接续皇位的阶段，现存君主名录对其具体施政记载不多；在位945—952年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思良"}]','圣慈文武皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-siping','段思平','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理开国君主，出身段氏，曾任大义宁通海节度使。传世记载称他因杨干贞猜忌而出走，在段思良、董迦罗及东部部族支持下组织军队，937年击败杨氏、建立大理，以洱海地区为统治中心。早期经历主要见后世地方史，部分细节带有传说色彩；944年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思平"}]','圣神文武皇帝','太祖','大理太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-siying','段思英','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段思平之子，父死后承继大理皇位，是建国初期第二位君主。其在位仅一年，随后由段思良继位；关于其短暂统治的具体政事，现有材料记载有限；在位944—945年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段思英"}]',NULL,NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sulian','段素廉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段素英之后继位的大理君主，使用明启年号。其在位十三年，延续段氏王统；现存资料主要保存世系、年号和在位时间，具体政绩不详；在位1009—1022年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素廉"}]','宣肃皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sulong','段素隆','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第八位君主，使用明通年号，在位四年后禅位或退位，继位者为段素真。其短暂统治处于段氏王位连续传承过程中，细节记载有限；在位1022—1026年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素隆"}]','秉义皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-sushun','段素顺','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第五位君主，承接段思聪之后的段氏统治。其在位十七年，处于大理早期政权延续与巩固阶段，具体政绩记载不详；在位968—985年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素顺"}]','应道皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-suxing','段素兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第十位君主，使用圣明、天明年号，在位三年即被废。其后由段思廉继位，标志段氏王统的一次转折；废立缘由在后世叙述中较简略；在位1041—1044年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素兴"}]','天明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-suying','段素英','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第六位君主，使用广明、明圣、明统等年号，在位二十四年。其长期统治构成大理早期较稳定的阶段之一，但关于具体制度或战事的记载有限；在位985—1009年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素英"}]','昭明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-suzhen','段素真','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理第九位君主，使用正治年号，在位十五年。其统治结束后由段素兴继位；具体施政事迹记载有限；在位1026—1041年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段素真"}]','圣德皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-xiangxing','段祥兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理君主，承接段智祥，在位时期蒙古帝国势力持续南进。其去世后段兴智继位，面对蒙古对云南的军事压力；在位1238—1251年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段祥兴"}]','孝义皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-xingzhi','段兴智','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理末代皇帝，段祥兴之子，蒙古军于1253年攻入大理后被俘并降元。其后获任大理总管，段氏以地方世袭总管身份延续，与皇帝统治时期相区别；在位1251—1254年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段兴智"}]',NULL,NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengchun','段正淳','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','高升泰之后复位的段氏君主，庙号中宗，在高氏辅政下恢复大理国号。高氏继续掌握重要政务，段正淳统治期间大理与宋保持往来；在位1096—1108年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段正淳"}]','文安皇帝','中宗','大理中宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengming','段正明','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理段氏君主，杨义贞之乱后继位，受到相国高氏家族的强力辅政。1094年高升泰取代段氏称帝，段正明退位；其退位为大理短暂“大中”政权及段氏复国埋下背景；在位1081—1094年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段正明"}]','保定皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengxing','段正兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段正严之后继位的大理君主，庙号景宗，在位二十四年。其统治处于大理与宋及周边势力长期交往的阶段，后由段智兴继位；可考具体政事仍较有限；在位1147—1171年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段正兴"}]','正康皇帝','景宗','大理景宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhengyan','段和誉','dali','["段正严","段政严"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段正淳之子，本名段和誉，庙号宪宗，是大理在位时间最长的君主之一。其朝延续高氏相国辅政格局，与宋朝维持交往，后禅位出家；在位1108—1147年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段和誉"}]','宣仁皇帝','宪宗','大理宪宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhilian','段智廉','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理段氏君主，承接段智兴，在位四年，使用凤历、元寿年号。其后由段智祥继位；相关传世资料主要见于君主世系和年表，个人政务活动记载不详；在位1200—1204年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段智廉"}]','亨天皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhixiang','段智祥','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理神宗，在位三十四年，是蒙古势力进入云南前长期执政的段氏君主。其后由段祥兴继位，大理仍维持独立统治并与周边政权往来；在位1204—1238年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段智祥"}]',NULL,'神宗','大理神宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-zhixing','段智兴','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','段正兴之后继位的大理君主，庙号宣宗，在位近三十年。其统治期间佛教在大理社会与王室文化中保持重要地位；后由段智廉继位；在位1171—1200年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/段智兴"}]','功极皇帝','宣宗','大理宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-shengtai','高升泰','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理相国高智升之子。高氏长期掌握大理军政，高升泰参与平定杨义贞之乱后继续辅政，1094年取代段正明称帝，改国号大中。1096年去世，临终命子高泰明还政段氏，段正淳继位；高氏仍保留重要军政权力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/高升泰"}]','富有圣德表正皇帝',NULL,'大中国皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ge-luofeng','阁罗凤','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','皮逻阁之子，唐封云南王，谥神武王，天宝年间与唐战并与吐蕃结盟。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阁罗凤"}]','神武王',NULL,'云南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('long-shun','隆舜','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主","皇帝"]','隆舜是世隆之子，承统后改国号为大封民。其在位时南诏仍与唐交战，也与唐恢复往来；897年权臣郑买嗣发动政变，隆舜被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/隆舜"},{"label":"《新唐书·南诏传》（识典古籍）","url":"https://www.shidianguji.com/book/LS0017/chapter/LS0017_1352"}]','武宣帝',NULL,'皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('luo-sheng','逻盛','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','细奴逻之子，谥兴宗王，庙号世宗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/逻盛"}]','兴宗王','世宗','诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('pi-luoge','皮逻阁','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','盛逻皮之子，728年继领蒙舍诏，承袭蒙氏在洱海以南的部族基础。唐朝为牵制吐蕃而支持其扩张，737年协助其攻取太和等地，738年兼并其余五诏，受封云南王，南诏由此成为统一的洱海政权。其后以太和为中心继续扩张，748年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/皮逻阁"},{"label":"《新唐书·南诏传》（识典古籍）","url":"https://www.shidianguji.com/book/LS0017/chapter/LS0017_1352"}]','归义王',NULL,'云南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('quan-fengyou','劝丰祐','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','劝丰祐承劝利晟之后在位三十余年。830年南诏军攻入成都外城并掳掠人口、工匠与物资，唐诏关系长期恶化；其后世隆称帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/劝丰祐"},{"label":"《新唐书·南诏传》（识典古籍）","url":"https://www.shidianguji.com/book/LS0017/chapter/LS0017_1352"}]','昭成王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('quan-lisheng','劝利晟','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','劝龙晟之弟，谥靖王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/劝利晟"}]','靖王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('quan-longsheng','劝龙晟','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','寻阁劝之子，谥幽王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/劝龙晟"}]','幽王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sheng-luopi','盛逻皮','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','逻盛之子，谥威成王，庙号太宗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/盛逻皮"}]','威成王','太宗','诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-long','世隆','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主","皇帝"]','世隆又称酋龙，是劝丰祐之子。859年即位后自称帝、改国号大礼，拒绝唐廷册封；南诏与唐爆发多次战争，后由其子隆舜继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/世隆"},{"label":"《新唐书·南诏传》（识典古籍）","url":"https://www.shidianguji.com/book/LS0017/chapter/LS0017_1352"}]','景庄帝',NULL,'皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shun-huazhen','舜化贞','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主","皇帝"]','舜化贞是隆舜之子，由郑买嗣拥立为南诏末王。郑氏掌握实权，902年夺位并终结蒙氏王统；南诏政权随之覆亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/舜化贞"},{"label":"《新唐书·南诏传》（识典古籍）","url":"https://www.shidianguji.com/book/LS0017/chapter/LS0017_1352"}]','孝哀帝',NULL,'皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xi-nuoluo','细奴逻','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','细奴逻是蒙舍诏首领，传统南诏王表将其列为蒙氏王统的开端。唐初他遣使交往并受授官号；后世世系称其子逻盛继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/细奴逻"},{"label":"《新唐书·南诏传》（识典古籍）","url":"https://www.shidianguji.com/book/LS0017/chapter/LS0017_1352"}]','奇嘉王','高祖','诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xun-gequan','寻阁劝','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','异牟寻之子，亦称新觉劝，谥孝惠王，在位仅一年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/寻阁劝"}]','孝惠王',NULL,'南诏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-yizhen','杨义贞','dali','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','大理将领杨义贞于1080年发动政变，杀段廉义并短暂称帝。其统治旋即被高氏势力推翻，段寿辉继位；后世君主名录将其列入，但其正统地位有限；在位1080年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨义贞"}]','上明皇帝',NULL,'大理皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-mouxun','异牟寻','nanzhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','异牟寻为阁罗凤之孙、凤伽异之子。早年受吐蕃控制并接受封号，后在郑回建议下转而归唐；唐廷册封他为南诏王，南诏与唐重建联盟。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/异牟寻"},{"label":"《新唐书·南诏传》（识典古籍）","url":"https://www.shidianguji.com/book/LS0017/chapter/LS0017_1352"}]','孝桓王',NULL,'南诏王','[]');
